import { Clanker } from 'clanker-sdk/v5';
import { createPublicClient, createWalletClient, http, isHex } from 'viem';
import { privateKeyToAccount } from 'viem/accounts';
import { base } from 'viem/chains';

const key = process.env.PRIVATE_KEY;
if (!key || !isHex(key)) throw new Error('PRIVATE_KEY is required.');
const account = privateKeyToAccount(key);
const publicClient = createPublicClient({ chain: base, transport: http() });
const wallet = createWalletClient({ account, chain: base, transport: http() });

const clanker = new Clanker({ wallet, publicClient });
const { txHash, waitForTransaction, error } = await clanker.deploy({
  name: 'My Token',
  symbol: 'TKN',
  image: 'ipfs://...',
  tokenAdmin: account.address,
  metadata: { description: 'My awesome token' },
});

if (error) throw error;
const result = await waitForTransaction();
if (result.error) throw result.error;
console.log(txHash, result.address, result.poolId);
